-- All accounts below are fake demo users. Passwords are stored as bcrypt hashes
-- generated by pgcrypto at cost 12; these throwaway demo values are documented in README.
ON CONFLICT (department_name) DO NOTHING;

ON CONFLICT (role_name) DO NOTHING;

ON CONFLICT (permission_name) DO NOTHING;

SELECT r.role_id, p.permission_id
FROM roles AS r
CROSS JOIN permissions AS p
WHERE r.role_name = 'Admin'
ON CONFLICT (role_id, permission_id) DO NOTHING;

SELECT r.role_id, p.permission_id
FROM roles AS r
JOIN permissions AS p ON p.permission_name = ANY(ARRAY[
  'DOCUMENT_READ', 'DOCUMENT_UPLOAD', 'BREAK_GLASS_REQUEST',
  'NOTIFICATION_READ', 'DASHBOARD_READ'
])
WHERE r.role_name = 'Doctor'
ON CONFLICT (role_id, permission_id) DO NOTHING;

SELECT r.role_id, p.permission_id
FROM roles AS r
JOIN permissions AS p ON p.permission_name = ANY(ARRAY[
  'DOCUMENT_READ', 'BREAK_GLASS_REQUEST', 'NOTIFICATION_READ', 'DASHBOARD_READ'
])
WHERE r.role_name = 'Nurse'
ON CONFLICT (role_id, permission_id) DO NOTHING;

SELECT r.role_id, p.permission_id
FROM roles AS r
JOIN permissions AS p ON p.permission_name = ANY(ARRAY[
  'DOCUMENT_READ', 'NOTIFICATION_READ', 'DASHBOARD_READ'
])
WHERE r.role_name = 'Staff'
ON CONFLICT (role_id, permission_id) DO NOTHING;

ON CONFLICT (category_name) DO NOTHING;

-- The plaintexts are demo-only. crypt() stores only salted bcrypt hashes at cost 12.
ON CONFLICT (email) DO NOTHING;
