INSERT INTO roles(role_name, description) VALUES
  ('Admin', 'Manages users, policies, audit review, and configuration.'),
  ('Doctor', 'Reads permitted policies and may submit policy drafts.'),
  ('Nurse', 'Reads permitted policies and may request emergency access.'),
  ('Staff', 'Reads permitted non-clinical policies.')
INSERT INTO permissions(permission_name, description) VALUES
  ('USER_ADMIN', 'Create and update user accounts.'),
  ('DOCUMENT_READ', 'Read documents allowed by document permissions.'),
  ('DOCUMENT_UPLOAD', 'Submit a document draft or version.'),
  ('DOCUMENT_APPROVE', 'Approve a version uploaded by another user.'),
  ('DOCUMENT_PERMISSION_MANAGE', 'Grant or revoke role access to a document.'),
  ('DOCUMENT_RETIRE', 'Retire a policy and notify dependent-document owners.'),
  ('DOCUMENT_REFERENCE_MANAGE', 'Add or remove document dependency references.'),
  ('AUDIT_READ', 'Read access audit events.'),
  ('AUDIT_VERIFY', 'Run and review audit-chain integrity checks.'),
  ('BREAK_GLASS_REQUEST', 'Request time-limited emergency document access.'),
  ('BREAK_GLASS_REVIEW', 'Review emergency access requests.'),
  ('NOTIFICATION_READ', 'Read and update the current user notifications.'),
  ('DASHBOARD_READ', 'Read dashboard summaries.')
